/* V4 early (runs right after the title screen is built): new logo at once, hide the login/start area until the rest of the game has loaded (no old-version flash) */
(function(){try{
const LG='data:image/webp;base64,';window.__LOGO=LG;
const st=document.createElement('style');st.id='v4_early_css';st.textContent='#splash .xl .xlg{position:absolute;inset:-6% -4%;display:block;background:url('+LG+') center/contain no-repeat;pointer-events:none}#splash .xl img,#splash .xl b{visibility:hidden!important}#splash:not(.v4r) .xau,#splash:not(.v4r) .xsoon,#splash:not(.v4r) #bgn{visibility:hidden!important}';
document.head.appendChild(st);
const sw=()=>{const x=document.querySelector('#splash .xl');if(x&&!x.querySelector('.xlg'))x.insertAdjacentHTML('beforeend','<i class="xlg"></i>')};sw();
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();window.__bip=e});
const sp=document.getElementById('splash');if(sp)new MutationObserver(sw).observe(sp,{childList:true,subtree:true});
}catch(e){console.log('v4 early',e)}})();
